package com.oldrepublic.client.vendor;

import com.oldrepublic.OldRepublicMod;
import com.oldrepublic.vendor.hub.HubNpc;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;
import net.minecraft.resources.Identifier;

/**
 * Renders Vessba the Hutt (spec MILESTONE_5.md 3.3, 18): her own {@link VessbaModel} in her mottled
 * sand-and-ochre hide with the kajidic's gold at her collar, wrists and tail ring
 * ({@code textures/entity/vessba/vessba.png}, generated by {@code tools/assets/gen_textures_hub.py}).
 * She is the {@code vessba} entity, a hub host ({@code HubNpc}), so she talks, greets and is restored
 * like the other hub people; only her look is her own.
 */
public class VessbaRenderer extends MobRenderer<HubNpc, LivingEntityRenderState, VessbaModel> {
	private static final Identifier TEXTURE = OldRepublicMod.id("textures/entity/vessba/vessba.png");

	public VessbaRenderer(EntityRendererProvider.Context context) {
		super(context, new VessbaModel(context.bakeLayer(VessbaModel.LAYER)), 1.1f);
	}

	@Override
	public LivingEntityRenderState createRenderState() {
		return new LivingEntityRenderState();
	}

	@Override
	public Identifier getTextureLocation(LivingEntityRenderState state) {
		return TEXTURE;
	}
}
